correctedCode:
#include <stdio.h>

int main() {
    int number;
    printf("Enter a number: ");
    if (scanf("%d", &number) != 1) {
        printf("Invalid input\n");
        return 1;
    }
    printf("Double: %d\n", number * 2);
    return 0;
}
